var CACLE='crinstalle_ca';
var CA_LE=0;   /* horodatage du CA affiche quand il vient du cache, 0 s'il est frais */
function caSave(cid,ca){try{localStorage.setItem(CACLE,JSON.stringify({client_id:cid,ca:ca,le:Date.now()}));}catch(e){}}
function caLire(cid){try{var d=JSON.parse(localStorage.getItem(CACLE));
  return (d&&d.client_id===cid&&d.ca)?d:null;}catch(e){return null;}}
function caOublier(){try{localStorage.removeItem(CACLE);}catch(e){}}
function caFrais(c){if(ACCT&&c&&c.mois_total!==undefined)caSave(ACCT.client_id,c);CA_LE=0;return c;}
/* on ne se rabat sur le cache que pour une VRAIE panne reseau :
   un « Acces refuse » doit continuer a ejecter l'utilisateur */
function caSecours(er){var d=ACCT?caLire(ACCT.client_id):null;
  if(d&&er&&er.reseau){CA_LE=d.le;return d.ca;}
  throw er;}
function caQuand(t,now){var d=new Date(t);
  var hh=('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);
  var j0=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime();
  if(t>=j0)return 'aujourd\u2019hui \u00e0 '+hh;
  if(t>=j0-86400000)return 'hier \u00e0 '+hh;
  return 'le '+('0'+d.getDate()).slice(-2)+'/'+('0'+(d.getMonth()+1)).slice(-2)+' \u00e0 '+hh;}
/* saisies encore sur le telephone ET datees du mois affiche :
   ce sont exactement celles qui manquent au total du serveur */
function caAttente(now){var m=fileMiennes(),n=0,s=0,i;
  var pref=now.getFullYear()+'-'+('0'+(now.getMonth()+1)).slice(-2)+'-';
  for(i=0;i<m.length;i++){if(m[i].statut!=='attente')continue;
    if((m[i].date||'').indexOf(pref)!==0)continue;
    n++;s+=parseFloat(m[i].total)||0;}
  return {n:n,somme:Math.round(s*100)/100};}
var CASVG='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>';
var ATSVG='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>';
/* apres un retour de reseau : si l'accueil affiche un CA venu du cache, on le recharge */
function caRafraichir(){var h=document.getElementById('s-home');
  if(CA_LE&&h&&h.classList.contains('on')&&navigator.onLine)goHome();}
function caBandeau(now){var b=document.getElementById('hm-cache');if(!b)return;
  now=now||new Date();
  var h='',a=caAttente(now);
  if(CA_LE){h+='<div class="cline">'+CASVG+'<span>Chiffres du serveur, arr\u00eat\u00e9s <b>'+esc(caQuand(CA_LE,now))+'</b>\u202f\u2014 pas de r\u00e9seau pour les mettre \u00e0 jour.</span></div>';}
  if(a.n){h+='<div class="cline att">'+ATSVG+'<span><b>'+a.n+' saisie'+(a.n>1?'s':'')+' en attente d\u2019envoi</b>\u202f: '+esc(fmt(a.somme))+' pas encore compt\u00e9'+(a.n>1?'s':'')+' dans le total ci-dessus.</span></div>';}
  b.innerHTML=h?('<div class="cbx">'+h+'</div>'):'';
  b.className=h?'on':'';}
/* ---------- recherche par jeton (v16) ---------- */
var RECH_MIN=2;
var RECH_SEQ=0;   /* numero de requete : une reponse en retard ne doit JAMAIS ecraser une plus recente */
var RECH_T=null;  /* minuterie de frappe */
var RECH_Q='';    /* derniere requete effectivement lancee */
function rechEls(){return {b:document.getElementById('hm-srchb'),w:document.getElementById('hm-srchwrap'),
  q:document.getElementById('hm-srchq'),x:document.getElementById('hm-srchx'),
  i:document.getElementById('hm-srchinfo'),r:document.getElementById('hm-srchres'),
  l:document.getElementById('hm-list'),p:document.getElementById('hm-pdf'),d:document.getElementById('hm-docs')};}
function rechListe(v){var e=rechEls(),k,n=['l','p','d'];
  for(k=0;k<n.length;k++){if(e[n[k]])e[n[k]].style.display=v?'':'none';}}
function rechInfo(t,ko){var e=rechEls();if(!e.i)return;e.i.textContent=t||'';e.i.className='srchinfo'+(ko?' ko':'');}
function rechAide(){rechInfo('Tape au moins '+RECH_MIN+' caract\u00e8res du jeton.');}
function rechBascule(){var e=rechEls();if(!e.w)return;
  if(e.w.classList.contains('on')){rechFermer();return;}
  e.w.classList.add('on');
  if(e.b){e.b.classList.add('on');e.b.setAttribute('aria-expanded','true');}
  if(e.x)e.x.classList.remove('on');
  if(e.q){e.q.value='';try{e.q.focus();}catch(_e){}}
  rechAide();}
function rechFermer(){var e=rechEls();if(!e.w)return;
  RECH_SEQ++;if(RECH_T){clearTimeout(RECH_T);RECH_T=null;}
  RECH_Q='';
  e.w.classList.remove('on');
  if(e.b){e.b.classList.remove('on');e.b.setAttribute('aria-expanded','false');}
  if(e.q)e.q.value='';
  if(e.x)e.x.classList.remove('on');
  if(e.r)e.r.innerHTML='';
  rechInfo('');rechListe(true);}
function rechVider(){var e=rechEls();if(e.q){e.q.value='';try{e.q.focus();}catch(_e){}}rechSaisie();}
function rechRendu(d){var e=rechEls();if(!e.r)return;
  var l=(d&&d.resultats)||[],h='',i;
  for(i=0;i<l.length;i++){var o=l[i];var dd=(o.date||'').split('-');
    h+='<button class="hrow" onclick="openFiche('+parseInt(o.id,10)+')"><span>'
      +'<span class="j" style="display:block">'+esc(o.jeton)+'</span>'
      +'<span class="m" style="display:block">'+esc(TLBL[o.typo]||o.typo)+' \u00b7 '+esc(o.sect)+' \u00b7 '+esc(dd[2]+'/'+dd[1]+'/'+dd[0])+'</span></span>'
      +'<span class="t">'+fmt(parseFloat(o.total)||0)
      +'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg></span></button>';}
  e.r.innerHTML=h;
  var n=parseInt(d&&d.n,10)||0;
  if(!n){rechInfo('Aucune saisie avec \u00ab\u202f'+RECH_Q+'\u202f\u00bb dans le jeton.');}
  else if(n>l.length){rechInfo(l.length+' saisies affich\u00e9es sur '+n+' trouv\u00e9es \u2014 pr\u00e9cise le jeton.');}
  else{rechInfo(n>1?(n+' saisies trouv\u00e9es'):'1 saisie trouv\u00e9e');}
  rechListe(false);}
function rechOuverte(){var w=document.getElementById('hm-srchwrap');return !!(w&&w.classList.contains('on'));}
/* au retour d'une fiche on RELANCE la recherche : une saisie modifiee ou supprimee
   ne doit pas rester affichee a partir d'un ancien resultat */
function rechRestaurer(){if(rechOuverte()&&RECH_Q.length>=RECH_MIN){rechListe(false);rechLancer(RECH_Q);}}
function rechSaisie(){var e=rechEls();if(!e.q)return;
  if(RECH_T){clearTimeout(RECH_T);RECH_T=null;}
  var brut=e.q.value||'';
  var v=brut.replace(/^\s+|\s+$/g,'');
  if(e.x)e.x.classList[brut.length?'add':'remove']('on');
  if(v.length<RECH_MIN){RECH_SEQ++;RECH_Q='';if(e.r)e.r.innerHTML='';rechAide();rechListe(true);return;}
  RECH_T=setTimeout(function(){rechLancer(v);},350);}
function rechLancer(v){if(!ACCT)return;
  var s=++RECH_SEQ;RECH_Q=v;
  rechInfo('Recherche\u2026');
  rpc('solo_recherche',{p_client:ACCT.client_id,p_cle:ACCT.cle,p_q:v}).then(function(d){
    if(s!==RECH_SEQ)return;   /* une frappe plus recente a pris la main */
    rechRendu(d);
  },function(er){
    if(s!==RECH_SEQ)return;
    var r=document.getElementById('hm-srchres');if(r)r.innerHTML='';
    rechInfo(er&&er.message?er.message:'Petit souci r\u00e9seau, r\u00e9essaie.',true);
    rechListe(true);});}
function rechInit(){var q=document.getElementById('hm-srchq');if(!q)return;
  q.addEventListener('input',rechSaisie);
  q.addEventListener('search',rechSaisie);   /* croix native du champ de recherche */
  q.addEventListener('keydown',function(ev){
    if(ev.key==='Escape'){rechFermer();return;}
    if(ev.key==='Enter'){ev.preventDefault();
      if(RECH_T){clearTimeout(RECH_T);RECH_T=null;}
      var v=(q.value||'').replace(/^\s+|\s+$/g,'');
      if(v.length>=RECH_MIN)rechLancer(v);
      try{q.blur();}catch(_e){}}});}
/* === v15 : file d'attente des saisies hors ligne === */
var FILECLE='crinstalle_file';
var FILE_MAX=50;
var FILE_EN_COURS=false;
function fileLire(){try{var a=JSON.parse(localStorage.getItem(FILECLE));return Array.isArray(a)?a:[];}catch(e){return [];}}
function fileEcrire(a){try{localStorage.setItem(FILECLE,JSON.stringify(a));return true;}catch(e){return false;}}
function fileMiennes(){if(!ACCT)return [];var a=fileLire(),o=[],i;
  for(i=0;i<a.length;i++)if(a[i].client_id===ACCT.client_id)o.push(a[i]);return o;}
function fileRetirer(id){var a=fileLire(),o=[],i;for(i=0;i<a.length;i++)if(a[i].id!==id)o.push(a[i]);fileEcrire(o);}
function fileMaj(id,ch){var a=fileLire(),i,k;for(i=0;i<a.length;i++)if(a[i].id===id){for(k in ch)a[i][k]=ch[k];}fileEcrire(a);}
/* met une saisie de cote ; renvoie l'entree ou null si la file est pleine */
function fileEnfiler(jeton,date,typo,sect,pp,metrage,com,force){
  if(!ACCT)return null;
  if(fileMiennes().length>=FILE_MAX)return null;
  var c=null;try{c=calcLocal();}catch(e){}
  var e={id:'f'+Date.now()+Math.floor(Math.random()*1000),client_id:ACCT.client_id,
    jeton:jeton,date:date,typo:typo,sect:sect,pp:!!pp,metrage:metrage||0,com:com||'',
    force:!!force,total:c?c.total:0,base:c?c.base:0,bApt:c?c.bApt:0,bPp:c?c.bPp:0,bMet:c?c.bMet:0,
    statut:'attente',message:'',le:Date.now()};
  var a=fileLire();a.push(e);
  if(!fileEcrire(a))return null;
  return e;}
/* ecran de confirmation pour une saisie mise en file */
function fileConfirmer(e){var d=(e.date||'').split('-');
  document.getElementById('sv-badge').textContent='Gardée sur ton téléphone';
  document.getElementById('sv-total').textContent=fmt(parseFloat(e.total)||0);
  var h='<div class="krow"><div class="k">Jeton</div><div class="v">'+esc(e.jeton)+'</div></div>'
   +'<div class="krow"><div class="k">Date</div><div class="v">'+esc(d[2]+'/'+d[1]+'/'+d[0])+'</div></div>'
   +'<div class="krow"><div class="k">Typologie</div><div class="v">'+esc(TLBL[e.typo]||e.typo)+'</div></div>'
   +'<div class="krow"><div class="k">Secteur</div><div class="v">'+esc(e.sect)+'</div></div>'
   +'<div class="krow"><div class="k">Base</div><div class="v">'+fmt(parseFloat(e.base)||0)+'</div></div>';
  if(parseFloat(e.bApt)>0)h+='<div class="krow"><div class="k">Bonus secteur</div><div class="v">+'+fmt(parseFloat(e.bApt))+'</div></div>';
  if(parseFloat(e.bPp)>0)h+='<div class="krow"><div class="k">Post-prod</div><div class="v">+'+fmt(parseFloat(e.bPp))+'</div></div>';
  if(parseFloat(e.bMet)>0)h+='<div class="krow"><div class="k">Métrage</div><div class="v">+'+fmt(parseFloat(e.bMet))+'</div></div>';
  h+='<div class="krow"><div class="k">Total estimé</div><div class="v">'+fmt(parseFloat(e.total)||0)+'</div></div>';
  if(e.com)h+='<div class="krow"><div class="k">Commentaire</div><div class="v" style="font-weight:500">'+esc(e.com)+'</div></div>';
  h+='<div class="krow"><div class="k">Envoi</div><div class="v" style="font-weight:500;color:var(--warn)">Dès le retour du réseau</div></div>';
  document.getElementById('sv-recap').innerHTML=h;
  buildFile();majBandeau();show('s-saved');}
/* liste des saisies en attente, affichee sur l'accueil ET sur Mon compte */
function buildFile(){var m=fileMiennes(),h='',i;
  if(m.length){
    h='<div class="lsthead"><div class="t">En attente d’envoi</div><div class="note">'+m.length+'</div></div><div class="rows">';
    for(i=0;i<m.length;i++){var e=m[i];var d=(e.date||'').split('-');
      h+='<div class="frow"><div class="fmid"><span class="j">'+esc(e.jeton)+'</span>'
       +'<span class="m">'+esc(TLBL[e.typo]||e.typo)+' · '+esc(e.sect)+' · '+esc(d[2]+'/'+d[1])+'</span>'
       +((e.statut!=='attente'&&e.message)?('<span class="m fmsg">'+esc(e.message)+'</span>'):'')
       +'</div><div class="fdte"><span class="t">'+fmt(parseFloat(e.total)||0)+'</span>'
       +'<span class="fchip'+(e.statut==='doublon'?' wa':(e.statut==='refuse'?' ko':''))+'">'
       +(e.statut==='doublon'?'à confirmer':(e.statut==='refuse'?'refusée':'en attente'))+'</span></div></div>';
      if(e.statut==='doublon')h+='<div class="fact"><button class="btn ghost" onclick="fileForcer(\''+e.id+'\')">Oui, envoyer quand même</button><button class="btn danger" onclick="fileJeter(\''+e.id+'\')">Supprimer</button></div>';
      if(e.statut==='refuse')h+='<div class="fact"><button class="btn danger" onclick="fileJeter(\''+e.id+'\')">Retirer de la liste</button></div>';
    }
    h+='</div>';}
  var ids=['hm-file','ok-file'];
  for(i=0;i<ids.length;i++){var el=document.getElementById(ids[i]);if(el)el.innerHTML=h;}}
function fileForcer(id){fileMaj(id,{statut:'attente',force:true,message:''});buildFile();fileEnvoyer();}
function fileJeter(id){fileRetirer(id);buildFile();majBandeau();}
/* envoi sequentiel ; l'index UNIQUE (client, tech, jeton, date) garantit l'absence de doublon */
function fileEnvoyer(){
  if(FILE_EN_COURS||!ACCT||!navigator.onLine)return Promise.resolve();
  var m=fileMiennes(),att=[],i;
  for(i=0;i<m.length;i++)if(m[i].statut==='attente')att.push(m[i]);
  if(!att.length)return Promise.resolve();
  FILE_EN_COURS=true;
  var suivant=function(k){
    if(k>=att.length)return Promise.resolve();
    var e=att[k];
    return rpc('solo_saisie',{p_client:ACCT.client_id,p_cle:ACCT.cle,p_jeton:e.jeton,p_date:e.date,
      p_typo:e.typo,p_secteur:e.sect,p_pp:!!e.pp,p_metrage:e.metrage||0,p_force:!!e.force,p_commentaire:e.com||''})
    .then(function(r){
      if(r&&r.doublon){fileMaj(e.id,{statut:'doublon',message:r.message});return suivant(k+1);}
      fileRetirer(e.id);return suivant(k+1);
    },function(er){
      var msg=(er&&er.message)?er.message:'';
      if(er&&er.reseau)return Promise.resolve();
      if(msg.indexOf('déjà saisi')>=0){fileRetirer(e.id);return suivant(k+1);}
      fileMaj(e.id,{statut:'refuse',message:msg||'Refusée par le serveur.'});return suivant(k+1);
    });};
  /* le verrou est TOUJOURS relache, meme si un imprevu casse la chaine :
     sinon la file resterait bloquee et les saisies ne partiraient plus jamais */
  var relacher=function(){FILE_EN_COURS=false;buildFile();majBandeau();};
  return Promise.resolve().then(function(){return suivant(0);})
    .then(relacher,relacher);}
/* === v14 : bloc hors ligne 1/3 — ouvrir l'app sans reseau === */
var HORSLIGNE_MSG='Tu es hors ligne \u2014 cette action a besoin du r\u00e9seau.';
var RESEAU_MSG='Connexion au serveur impossible ou trop lente \u2014 r\u00e9essaie dans un instant.';
var MECLE='crinstalle_me';
function meSave(cid,me){try{localStorage.setItem(MECLE,JSON.stringify({client_id:cid,me:me,le:Date.now()}));}catch(e){}}
function meLire(cid){try{var d=JSON.parse(localStorage.getItem(MECLE));
  return (d&&d.client_id===cid&&d.me)?d:null;}catch(e){return null;}}
function meOublier(cid){try{var d=JSON.parse(localStorage.getItem(MECLE));
  if(d&&d.client_id===cid)localStorage.removeItem(MECLE);}catch(e){}}
/* ouvre l'app sur le profil memorise ; renvoie false si aucun cache */
function demarrerHorsLigne(cid,cle){var d=meLire(cid);if(!d)return false;
  ACCT={client_id:cid,cle:cle,me:d.me};
  buildOkScreen({compte:d.me.compte,prenom:d.me.prenom,operateur:d.me.operateur,tarifs:d.me.tarifs,nouveau:false});
  document.getElementById('btn-new').style.display='flex';
  document.getElementById('btn-home').style.display='flex';
  document.getElementById('btn-regl').style.display=d.me.equipe?'none':'flex';
  if(d.me.equipe){var op=document.getElementById('ok-profil');if(op)op.innerHTML='';}
  buildAbo();majBandeau();buildFile();fileEnvoyer();
  if(aboLocked(d.me)){show('s-abo');return true;}
  /* on affiche TOUT DE SUITE un ecran utilisable, sans attendre le reseau :
     hors ligne un fetch peut agoniser plusieurs secondes, et l'utilisateur
     resterait devant l'ecran d'inscription entre-temps */
  show('s-ok');
  /* si on connait deja le CA du mois, l'accueil est utilisable hors ligne :
     goHome() retombe tout seul sur le cache quand le reseau manque */
  if(navigator.onLine||caLire(cid))goHome();
  return true;}
/* rafraichit le profil sans jamais deplacer l'utilisateur */
function rafraichirProfil(){if(!ACCT)return;
  rpc('solo_me',{p_client:ACCT.client_id,p_cle:ACCT.cle}).then(function(m){
    if(m&&m.tarifs){ACCT.me=m;meSave(ACCT.client_id,m);}majBandeau();}).catch(function(){majBandeau();});}
/* bandeau discret « hors ligne » */
function majBandeau(){var n=0;try{n=fileMiennes().length;}catch(e){}var b=document.getElementById('offbar');
  if(!b){b=document.createElement('div');b.id='offbar';b.setAttribute('role','status');document.body.appendChild(b);}
  b.className=navigator.onLine?'':'on';
  document.body.classList.toggle('hl',!navigator.onLine);
  b.innerHTML='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M2 2l20 20"/><path d="M5 12.5a9 9 0 013.6-2.4"/><path d="M8.5 16a4.5 4.5 0 015.2-.8"/><path d="M12 19.5h.01"/><path d="M19 12.5a9 9 0 00-4.6-2.6"/></svg>'
    +'<span>'+(n>0?('Hors ligne — '+n+' saisie'+(n>1?'s':'')+' en attente, elle'+(n>1?'s partiront':' partira')+' au retour du réseau'):'Hors ligne — tes saisies sont gardées et envoyées au retour du réseau')+'</span>';}
window.addEventListener('online',function(){majBandeau();rafraichirProfil();Promise.resolve(fileEnvoyer()).then(caRafraichir,caRafraichir);});
window.addEventListener('offline',majBandeau);
majBandeau();
var NAVMAP={'s-home':'s-home','s-docs':'s-docs','s-docadd':'s-docs','s-ok':'s-ok'};
function navSync(id){var cible=(NAVMAP||{})[id]||'';document.body.classList.toggle('nav',!!cible&&!!ACCT);
  var t=document.querySelectorAll('#tabs .tab');for(var i=0;i<t.length;i++)t[i].classList.toggle('on',t[i].getAttribute('data-tab')===cible);}
/* === v13 : marques des operateurs === */
