function openSaisie(){if(!ACCT)return;ss={date:'auj',typo:null,sect:'APT',pp:false,editId:null};document.getElementById('sa-ttl').textContent='Nouvelle intervention';document.getElementById('sa-jeton').value='';document.getElementById('sa-met').value='';document.getElementById('sa-com').value='';document.getElementById('sa-date').style.display='none';document.getElementById('sa-date').value='';var sw=document.getElementById('sw-spp');sw.classList.remove('on');sw.setAttribute('aria-checked','false');pickDate('auj');var mt=ACCT.me.tarifs||{},h='',i;for(i=0;i<TYPOS.length;i++){var k=TYPOS[i];if(mt[k]===undefined||mt[k]===null)continue;h+='<button class="chip" role="radio" aria-checked="false" data-t="'+k+'" onclick="pickTypo(this,\''+k+'\')">'+TLBL[k]+'</button>';}document.getElementById('sa-typos').innerHTML=h;h='';for(i=0;i<SECTS.length;i++){h+='<button class="chip'+(SECTS[i]===ss.sect?' sel':'')+'" role="radio" aria-checked="'+(SECTS[i]===ss.sect)+'" data-s="'+SECTS[i]+'" onclick="pickSect(this,\''+SECTS[i]+'\')">'+SECTS[i]+'</button>';}document.getElementById('sa-sects').innerHTML=h;err('err-saisie');document.getElementById('warn-doublon').classList.remove('on');recalc();show('s-saisie');document.getElementById('sa-jeton').focus();}
function pickDate(w){ss.date=w;var ids=['d-auj','d-hier','d-autre'],ks=['auj','hier','autre'];for(var i=0;i<3;i++){var el=document.getElementById(ids[i]);el.classList.toggle('sel',ks[i]===w);el.setAttribute('aria-checked',ks[i]===w?'true':'false');}var di=document.getElementById('sa-date');di.style.display=w==='autre'?'block':'none';recalc();}
function pickTypo(el,k){ss.typo=k;var c=document.querySelectorAll('#sa-typos .chip');for(var i=0;i<c.length;i++){c[i].classList.remove('sel');c[i].setAttribute('aria-checked','false');}el.classList.add('sel');el.setAttribute('aria-checked','true');recalc();}
